/**
 * v0.3 follow-up 2: THIRD-PARTY-NOTICES (generated by scripts/third-party-notices.ts) is current: every production
 * dependency of the server and the web app with its licence texts, and the fonts' OFL texts. CI also runs the script
 * with --check. Regenerate with `node scripts/third-party-notices.ts`.
 */
import { readFileSync } from 'node:fs';
import path from 'node:path';
import { describe, expect, it } from 'vitest';
import { render } from '../../../../scripts/third-party-notices.ts';

const ROOT = path.resolve(import.meta.dirname, '../../../..');

describe('third-party notices (v0.3 follow-up 2)', () => {
  const text = render();
  it('the committed file matches the installed production dependencies', () => {
    expect(readFileSync(path.join(ROOT, 'THIRD-PARTY-NOTICES'), 'utf8') === text, 'THIRD-PARTY-NOTICES is out of date: run node scripts/third-party-notices.ts').toBe(true);
  });
  it('covers both apps, the fonts and their licence texts', () => {
    for (const dep of ['fastify 5.12.7', 'openid-client', 'react 19', 'zod ', '@codemirror/view', 'uplot', 'qrcode-generator', 'redis 5']) expect(text).toContain(dep);
    expect(text).toContain('Atkinson Hyperlegible Next');
    expect(text).toContain('Atkinson Hyperlegible Mono');
    expect(text).toContain('SIL OPEN FONT LICENSE Version 1.1');
    expect(text).toContain('Permission is hereby granted, free of charge');
    expect(text).not.toContain('/Users/');
    expect(text).not.toMatch(/ships no licence file\. /);
  });
});
